#!/bin/bash
# Read only the request generated by the Go wrapper in its private directory.
set -euo pipefail
[[ $# == 1 && -n "$TMPDIR" && "$1" == "$TMPDIR"/native-*-input.json ]]
[[ -f "$1" && ! -L "$1" ]]
[[ -f /run/native-recovery/tools.yml && ! -L /run/native-recovery/tools.yml ]]
[[ -f /run/native-recovery/tls/server.crt && ! -L /run/native-recovery/tls/server.crt ]]
exec /opt/java/openjdk/bin/java -Xms32m -Xmx128m -XX:MaxDirectMemorySize=32m \
    -Djava.io.tmpdir="$TMPDIR" -Duser.home="$TMPDIR" \
    -Drocketmq.client.logRoot="$TMPDIR" \
    -Dtls.enable=true -Dtls.client.authServer=true \
    -Dtls.client.trustCertPath=/run/native-recovery/tls/server.crt \
    -Dm3.native.tools=/run/native-recovery/tools.yml \
    -cp '/opt/native-recovery/native-managed.jar:/opt/native-recovery/lib/*' \
    NativeHalfManaged < "$1"
